import {elasticAllocation} from './gpu-allocation.js';
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));

export function elasticFields(){return `<details><summary>弹性卡数（可选）</summary><label><input name="elastic" type="checkbox">按最多可用合法卡数启动；上方卡数为最大值</label><div class="train-grid"><label>最低卡数<input name="min-cards" type="number" min="1" value="1"></label><label>Global batch<input name="global-batch" type="number" min="1" placeholder="例如 256"></label><label>每卡 micro batch<input name="micro-batch" type="number" min="1" placeholder="例如 8"></label></div><label><input name="auto-expand" type="checkbox">空卡释放后，保存并恢复到更大的合法卡数</label><p class="muted" id="elastic-note">自动扩卡需选独立调度、保存让位、自动恢复，并确认训练已接入 checkpoint 和弹性 batch 适配器。训练按实际卡数启动 DDP 并计算梯度累积；global batch 和 LR 保持不变。</p></details>`;}
export function elasticFromForm(form,cards,scheduling){return form.get('elastic')?elasticAllocation({minCards:Number(form.get('min-cards')),globalBatch:Number(form.get('global-batch')),microBatch:Number(form.get('micro-batch')),autoExpand:form.get('auto-expand')==='on'},cards,scheduling).elastic:null;}
export function allocationSummary(job){return job.elastic?`<small>弹性 ${esc(job.elastic.minCards)}–${esc(job.cards)} 张 · 当前 ${esc(job.actualCards??job.assignedIndices?.length??0)} 张</small><small>合法卡数 ${esc((job.allowedGpuCounts||[]).join(','))}${job.elastic.autoExpand?' · 保存后自动扩卡':''}</small>`:`<small>${esc(job.cards)} 张${job.assignedIndices?.length?' · GPU '+esc(job.assignedIndices.join(',')):''}</small>`;}
